def wrap(text, width):
    result = []
    paragraphs = text.split('\n')
    for para in paragraphs:
        words = para.split()
        # break long words into pieces
        pieces = []
        for w in words:
            if len(w) > width:
                for i in range(0, len(w), width):
                    pieces.append(w[i:i+width])
            else:
                pieces.append(w)
        if not pieces:
            result.append('')
            continue
        lines = []
        current = ''
        for p in pieces:
            if current == '':
                candidate = p
            else:
                candidate = current + ' ' + p
            if len(candidate) <= width:
                current = candidate
            else:
                lines.append(current)
                current = p
        if current != '':
            lines.append(current)
        result.extend(lines)
    return result

